INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Brauche ich 2 geliehene Bits, um 4 Subnetze aus /24 zu machen?', 2, '[{"text": "Ja", "correct": true, "because": "2^2 = 4 Subnetze"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske entsteht bei /24 mit 4 Subnetzen?', 3, '[{"text": "/26", "correct": true, "because": "24 + 2 Bits = /26"}, {"text": "/25", "correct": false, "because": "Nur 2 Subnetze"}, {"text": "/27", "correct": false, "because": "8 Subnetze"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /26 ergibt 4 Subnetze aus /24. b) Jedes Subnetz hat 62 Hosts.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 2^2 = 4, b) 2^(32-26) - 2 = 62"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Aufteilung?', 4, '[{"text": "Geliehene Bits", "correct": false, "because": "Bestimmen Subnetzanzahl"}, {"text": "Hostanzahl", "correct": false, "because": "Ergibt sich aus Maske"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /26 aus /24 genau 4 Subnetze ergibt?', 2, '[{"text": "Ja", "correct": true, "because": "2^(26-24) = 4"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schrittweite hat /26 bei 4 Subnetzen?', 3, '[{"text": "64", "correct": true, "because": "2^(32-26) = 64"}, {"text": "32", "correct": false, "because": "Für /27"}, {"text": "128", "correct": false, "because": "Für /25"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche entstehen bei 192.168.1.0/24 mit /26?', 5, '[{"text": "192.168.1.0-63", "correct": true, "because": "Erstes Subnetz"}, {"text": "192.168.1.64-127", "correct": true, "because": "Zweites Subnetz"}, {"text": "192.168.1.128-191", "correct": true, "because": "Drittes Subnetz"}, {"text": "192.168.1.192-255", "correct": true, "because": "Viertes Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /26 hat 64 Adressen pro Subnetz. b) 4 Subnetze brauchen /28. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/28 ergibt 16 Subnetze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Aufteilung?', 4, '[{"text": "Netzwerkmaske", "correct": false, "because": "Definiert Subnetze"}, {"text": "Inkrement", "correct": false, "because": "Bestimmt Bereiche"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat jedes /26-Subnetz aus /24 62 nutzbare Hosts?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-26) - 2 = 62"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Broadcastadresse hat das zweite Subnetz von 10.0.0.0/24 mit /26?', 4, '[{"text": "10.0.0.127", "correct": true, "because": "64-127, letzte Adresse"}, {"text": "10.0.0.63", "correct": false, "because": "Erstes Subnetz"}, {"text": "10.0.0.191", "correct": false, "because": "Drittes Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass /26 nur 2 Subnetze aus /24 ergibt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "2^2 = 4 Subnetze"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Aufteilung?', 3, '[{"text": "Anzahl Subnetze", "correct": true, "because": "Bestimmt geliehene Bits"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 4 Subnetze aus /24 sind /26. b) Jedes Subnetz hat 128 Adressen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist 64 Adressen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkadressen hat 172.16.0.0/24 mit /26?', 5, '[{"text": "172.16.0.0", "correct": true, "because": "Erstes Subnetz"}, {"text": "172.16.0.64", "correct": true, "because": "Zweites Subnetz"}, {"text": "172.16.0.128", "correct": true, "because": "Drittes Subnetz"}, {"text": "172.16.0.192", "correct": true, "because": "Viertes Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Aufteilung unwichtig?', 3, '[{"text": "Geliehene Bits", "correct": false, "because": "Bestimmen Subnetze"}, {"text": "Inkrement", "correct": false, "because": "Definiert Bereiche"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat /26 aus /24 ein Inkrement von 64?', 3, '[{"text": "Ja", "correct": true, "because": "2^(32-26) = 64"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das dritte Subnetz von 192.168.1.0/24 mit /26 bei 192.168.1.128 anfängt?', 2, '[{"text": "Ja", "correct": true, "because": "Inkrement 64, 128-191"}, {"text": "Nein", "correct": false, "because": "Korrekte Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hostanzahl hat jedes Subnetz bei /24 mit 4 Subnetzen?', 4, '[{"text": "62", "correct": true, "because": "2^(32-26) - 2 = 62"}, {"text": "64", "correct": false, "because": "Ohne Abzug"}, {"text": "60", "correct": false, "because": "Falsche Subtraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Broadcastadresse hat das vierte Subnetz von 10.0.0.0/24 mit /26?', 3, '[{"text": "10.0.0.255", "correct": true, "because": "192-255, letzte Adresse"}, {"text": "10.0.0.191", "correct": false, "because": "Drittes Subnetz"}, {"text": "10.0.0.254", "correct": false, "because": "Vorletzte Adresse"}]');
